220	func TestCorrectionIdempotentAndMismatch(t *testing.T) {
221		m := newMap(t, baseConfig())
222		if _, err := m.ImportSegment(corrSegment()); err != nil {
223			t.Fatal(err)
224		}
225		req := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Variance: 2}}
226		first, err := m.Correct(req)
227		if err != nil {
228			t.Fatal(err)
229		}
230	
231		// 同标识同内容：返回首次结果，不再修改数据，也不新增记录。
232		again, err := m.Correct(req)
233		if err != nil {
234			t.Fatalf("duplicate correction: %v", err)
235		}
236		if !recordsEqual(again, first) {
237			t.Fatalf("duplicate returned %+v, want %+v", again, first)
238		}
239		if recs, _ := m.Corrections(); len(recs) != 1 {
240			t.Fatalf("duplicate added a record: %v", recs)
241		}
242		cur, _ := m.CurrentPose()
