248		diff := req
249		diff.Target.Variance = 3
250		_, err = m.Correct(diff)
251		r, ok := AsRejectError(err)
252		if !ok || r.Kind != RejectCorrectionMismatch || r.Landmark != "c1" {
253			t.Fatalf("mismatch err = %v", err)
254		}
255		if recs, _ := m.Corrections(); len(recs) != 1 {
256			t.Fatalf("mismatch added a record: %v", recs)
257		}
258	
259		// 校正后重复导入原轨迹段：返回首次导入结果，不撤销校正、不增加次数。
