461	
462		m2, err := Open(path)
463		if err != nil {
464			t.Fatalf("open legacy: %v", err)
465		}
466		defer m2.Close()
467	
468		// 旧文件可正常打开、查询。
469		p, err := m2.PoseAt(100)
470		if err != nil || p.X != 1 {
