499	
500		// 仅覆盖依据完整新范围的校正可成功；旧观测贡献固定不变。
501		rec, err := m2.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 2.0, Y: 0}})
502		if err != nil {
