663		f3 := []Frame{{Time: 1, DX: 2, Observations: []Observation{{ID: "a", X: 3, Y: math.Copysign(0, -1)}}}}
664		f4 := []Frame{{Time: 1, DX: 2, Observations: []Observation{{ID: "a", X: 3, Y: 0.0}}}}
665		if canonicalHash(f3) == canonicalHash(f4) {
666			t.Fatal("+0/-0 should differ by bit hash")
