import itertools

d = 1.0

def admit(mean, count, p):
    # seed may be None
    if count == 0:
        return (p, 1, True)
    dist = abs(p - mean)
    if dist > d + 1e-12:
        return (mean, count, False)
    return (mean + (p - mean)/(count+1), count+1, True)

def replay(seed, seq):
    mean, count = seed
    for p in seq:
        mean, count, ok = admit(mean, count, p)
        if not ok:
            return False
    return True

# grid of exact-binary-friendly offsets
grid = [-1.5, -1.0, -0.5, 0.0, 0.5, 1.0, 1.5]

# multiset sizes 4..6 with points from grid; require two orders A,B that both
# legally import (seed 0), and under shift s, A accepts, B rejects.
found = []
for n in (4, 5, 6):
    for combo in itertools.combinations_with_replacement(grid, n):
        span = max(combo) - min(combo)
        if span < 1.5:   # need room for order dependence
            continue
        perms = set(itertools.permutations(combo))
        for s in (-0.5, -0.25, -1.0):
            shifted = tuple(round(p+s, 4) for p in combo)
            legal_orders = [p for p in perms if replay((0.0,1), p)]
            post_orders = {}
            for p in legal_orders:
                ps = tuple(round(x+s,4) for x in p)
                post_orders[p] = replay((0.0,1), ps)
            accepts = [p for p,v in post_orders.items() if v]
            rejects = [p for p,v in post_orders.items() if not v]
            if accepts and rejects:
                found.append((combo, s, accepts[0], rejects[0]))
    if found:
        break

for f in found[:10]:
    print(f)
EOF
