cp posemap/correction.go /tmp/correction.go.bak
# Mutation A: 同帧同路标观测只保留一条（模拟"合并成一次观测"）
python3 - <<'EOF'
p='posemap/correction.go'; s=open(p).read()
old="""	for j := 1; j <= end; j++ {
		src := st.sources[j-1]
		if src == nil {
			continue // 旧文件帧：观测已计入对应出现的 legacy 起点
		}"""
new="""	for j := 1; j <= end; j++ {
		src := st.sources[j-1]
		if src == nil {
			continue // 旧文件帧：观测已计入对应出现的 legacy 起点
		}
		seenFrame := map[string]bool{}
		var dedup []Observation
		for _, ob := range src.observations {
			if !seenFrame[ob.ID] {
				seenFrame[ob.ID] = true
				dedup = append(dedup, ob)
			}
		}
		src = &frameSource{moveVariance: src.moveVariance, observations: dedup}"""
assert old in s; open(p,'w').write(s.replace(old,new))
EOF
go test -run 'SameFrame' ./... 2>&1 | grep -E 'FAIL|ok|PASS' | head; cp /tmp/correction.go.bak posemap/correction.go
# Mutation B: 冲突时泄漏暂存状态（模拟非原子提交）
python3 - <<'EOF'
p='posemap/correction.go'; s=open(p).read()
old="""			case obsConflict:
				return CorrectionRecord{}, &RejectError{"""
new="""			case obsConflict:
				if occ := st.landmarks[ob.ID].appearances[k.num-1]; occ != nil {
					occ.x, occ.y, occ.count = a.x, a.y, a.count
				}
				return CorrectionRecord{}, &RejectError{"""
assert old in s; open(p,'w').write(s.replace(old,new))
EOF
go test -run 'SameFrame' ./... 2>&1 | grep -E 'FAIL|ok ' | head; cp /tmp/correction.go.bak posemap/correction.go
